"""Bind a transparent executable adapter to the exact team-endorsed control-room intervention."""
from __future__ import annotations

from dataclasses import dataclass
import hashlib
import json
from pathlib import Path


RULES = {
    'timestamp-job-aid': ('aid_check', 'compare_display_to_authored_reference', 'mark_paper_uncertain'),
    'stop-and-handoff': ('latched_stop', 'send_required_fields', 'require_acknowledgement'),
    'sensor-staleness-rehearsal': ('prepare_reference', 'prestart_check', 'sensor_staleness_scope_only',
                                  'local_log', 'twenty_minute_limit'),
    'completed-scientist-consultation': ('no_diagnosis_certification', 'no_delayed_transfer_claim'),
}


@dataclass(frozen=True)
class FrozenProgram:
    """Executable permissions derived from this versioned manual clause-to-rule adapter."""

    sha256: str
    committed_units: int
    allowed_features: tuple[str, ...]
    core_endorsers: tuple[str, ...]
    handoff_fields: tuple[str, ...] = ('alarm', 'last_known_values_uncertain', 'timestamp',
                                     'contradiction', 'ai_priority', 'stopped_status')
    diagnosis_assessment_funded: bool = False
    delayed_probe_funded: bool = False


def require(condition: bool, message: str) -> None:
    """Fail closed without relying on optimization-sensitive assertions."""
    if not condition:
        raise ValueError(message)


def read_json(path: Path) -> dict:
    """Read one explicit JSON object without changing retained evidence."""
    return json.loads(path.read_text())


def validate_model(model: dict) -> None:
    """Reject invalid timing and behavior inputs before any simulation is executed."""
    require(model['model_id'] == 'controlroom-deployment-v1', 'Unknown deployment model')
    require(model['allowed_initial_features'] == ['sensor_staleness'], 'Adapter cannot expand frozen scope')
    time = model['time_seconds']
    require([time[k] for k in ['practice_start', 'handoff', 'handoff_window_end', 'end']]
            == [180, 780, 1080, 1200], 'Frozen 3/10/5/2-minute allocation changed')
    require(0 <= time['reference_prepare'] < time['reference_check'] < time['aid_check']
            < time['practice_start'], 'Preflight must fit inside the funded briefing segment')
    require(0 < time['ack_delay'] <= 300, 'Invalid acknowledgement delay')
    for profile in model['behavior_profiles'].values():
        require(all(type(v) is int and 0 < v < 600 for v in profile.values()), 'Invalid behavior timing')
    ids = [s['id'] for s in model['scenarios']]
    require(len(ids) == len(set(ids)), 'Duplicate episode ID')
    for scenario in model['scenarios']:
        require(scenario['behavior_profile'] in model['behavior_profiles'], 'Unknown behavior profile')
        require(all(type(v) is bool for v in scenario['initial'].values()), 'Initial flags must be Boolean')
        for change in scenario['environment_changes']:
            require(type(change['at']) is int and 0 <= change['at'] <= time['end'], 'Invalid event time')
            require(all(type(v) is bool for v in change['set'].values()), 'Environment flags must be Boolean')


def compile_program(root: Path, model: dict) -> FrozenProgram:
    """Validate exact bytes, actual endorsements and every clause-to-rule mapping."""
    validate_model(model)
    raw = (root / model['frozen_path']).read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    receipt = read_json(root / model['receipt_path'])
    require(digest == model['frozen_sha256'] == receipt['sha256'], 'Frozen intervention hash changed')
    artifact = json.loads(raw)
    actions = {a['id']: a for a in artifact['actions']}
    require(set(actions) == set(model['action_mapping']) == set(RULES), 'Action coverage differs from frozen plan')
    for aid, mapping in model['action_mapping'].items():
        require(mapping['source_clause'] == actions[aid]['action'], f'Clause changed: {aid}')
        require(tuple(mapping['rules']) == RULES[aid], f'Unsupported adapter rule: {aid}')
    require(artifact['budget_spent'] == sum(a['cost'] for a in actions.values()) == 7, 'Frozen cost changed')
    approvals = [read_json(root / model['case_path'] / 'responses' / name)
                 for name in receipt['endorsement_files']]
    require({a['actor'] for a in approvals} == {'operator', 'safety'}, 'Actual joint authority missing')
    require(all(a['endorsed'] is True and a['artifact_sha256'] == digest for a in approvals),
            'Exact-byte endorsement missing')
    release = read_json(root / model['release_path'])
    primary = [s for s in model['scenarios'] if s['kind'] == 'primary']
    require([(s['difficulty'], s['source_event']) for s in primary]
            == [(e['difficulty'], e['event']) for e in release['events']], 'Original event description changed')
    return FrozenProgram(digest, artifact['budget_spent'], tuple(model['allowed_initial_features']),
                         tuple(sorted(a['actor'] for a in approvals)))
"""Execute a frozen control-room procedure against an event-driven synthetic environment."""
from __future__ import annotations

import copy
import hashlib
import heapq
import json

from controlroom_contract import FrozenProgram


def freshness_status(display: dict, reference: dict | None) -> str:
    """Compare only operator-visible records, without an invented numerical age threshold."""
    if reference is None:
        return 'missing_reference'
    if display == reference:
        return 'current'
    if display['timestamp'] != reference['timestamp']:
        return 'contradiction'
    if display['state_id'] < reference['state_id']:
        return 'older_state'
    return 'indeterminate_match'


class DeploymentSimulator:
    """Maintain virtual time, operational state and a complete chained transition trace."""

    def __init__(self, program: FrozenProgram, model: dict, scenario: dict) -> None:
        """Create one independent episode without looking ahead at future failures."""
        self.program, self.model, self.scenario = program, model, scenario
        self.time = model['time_seconds']
        self.profile = model['behavior_profiles'][scenario['behavior_profile']]
        self.truth = copy.deepcopy(model['script_truth'])
        display = model['stale_display'] if scenario['initial']['sensor_stale'] else self.truth
        self.state = {'phase': 'preparing', 'flags': copy.deepcopy(scenario['initial']),
                      'display': copy.deepcopy(display), 'reference': None, 'reference_checked': False,
                      'aid_checked': False, 'practice_started': False, 'withheld': False,
                      'stopped': False, 'stop_at': None, 'inspection': None, 'accepted_items': [],
                      'handoff_payload': None, 'handoff_attempted': False, 'ack_at': None,
                      'paper_freshness': 'uncertain', 'paper_cleared_stop': False}
        self.queue: list[tuple[int, int, str, dict]] = []
        self.trace: list[dict] = []
        self.serial, self.clock = 0, 0
        self.previous = program.sha256
        self._schedule_contract()

    def schedule(self, at: int, kind: str, payload: dict | None = None) -> None:
        """Schedule a concrete event with stable ordering and no wall-clock waiting."""
        if at < self.clock or at > self.time['end']:
            raise ValueError('Event outside the executable time horizon')
        self.serial += 1
        heapq.heappush(self.queue, (at, self.serial, kind, payload or {}))

    def _schedule_contract(self) -> None:
        """Instantiate the funded time segments and independent environment timeline."""
        self.schedule(0, 'scope_gate')
        for key in ['reference_prepare', 'reference_check', 'aid_check']:
            self.schedule(self.time[key], key)
        self.schedule(self.time['practice_start'], 'practice_start')
        self.schedule(self.time['practice_start'] + self.profile['inspect_after_practice_start'], 'inspect')
        self.schedule(self.time['practice_start'] + self.profile['accept_after_practice_start'], 'accept')
        self.schedule(self.time['handoff'], 'handoff')
        self.schedule(self.time['handoff'] + 20, 'paper_check')
        self.schedule(self.time['end'], 'finish')
        for change in self.scenario['environment_changes']:
            self.schedule(change['at'], 'environment', change['set'])

    def _scope_gate(self, payload: dict) -> dict:
        """Enforce the actual dual authority and currently declared release scope."""
        excluded = sorted(set(self.scenario['declared_features']) - set(self.program.allowed_features))
        if excluded:
            self.state.update(withheld=True, phase='withheld')
        return {'result': 'start_withheld' if excluded else 'scope_permitted',
                'excluded_features': excluded, 'actual_endorsers': list(self.program.core_endorsers)}

    def _reference_prepare(self, payload: dict) -> dict:
        """Implement safety's authored local event record inside the funded briefing time."""
        if not self.state['flags']['reference_available']:
            return {'result': 'reference_missing'}
        self.state['reference'] = copy.deepcopy(self.truth)
        if not self.state['flags']['reference_correct']:
            self.state['reference']['state_id'] -= 1
        return {'result': 'reference_prepared', 'source': 'authored_local_event_record'}

    def _reference_check(self, payload: dict) -> dict:
        """Check safety's own scripted reference, not an independently verified physical clock."""
        valid = self.state['reference'] == self.truth
        self.state['reference_checked'] = valid
        return {'result': 'reference_check_passed' if valid else 'reference_check_failed'}

    def _aid_check(self, payload: dict) -> dict:
        """Check the realized aid's comparator, stop triggers and recipient before practice."""
        self.state['aid_checked'] = self.state['flags']['aid_check_passes']
        return {'result': 'aid_check_passed' if self.state['aid_checked'] else 'aid_check_failed',
                'procedure': 'compare_display_to_local_reference', 'recipient': 'safety',
                'stop_triggers': ['contradiction', 'older_state', 'missing_reference', 'indeterminate_match']}

    def _practice_start(self, payload: dict) -> dict:
        """Start only after the actual preparation events have passed their checks."""
        ready = self.state['reference_checked'] and self.state['aid_checked']
        self.state.update(practice_started=ready, withheld=not ready,
                          phase='active' if ready else 'withheld')
        return {'result': 'practice_started' if ready else 'start_withheld', 'preflight_passed': ready}

    def _stop(self, reason: str) -> dict:
        """Latch a stop without adding a restart or repair procedure."""
        if not self.state['stopped']:
            self.state['stop_at'] = self.clock
        self.state.update(stopped=True, phase='stopped')
        return {'result': 'stopped', 'reason': reason}

    def _inspect(self, payload: dict) -> dict:
        """Let the synthetic actor execute the aid using only visible display/reference fields."""
        status = freshness_status(self.state['display'], self.state['reference'])
        self.state['inspection'] = status
        return self._stop(status) if status != 'current' else {'result': 'freshness_passed'}

    def _accept(self, payload: dict) -> dict:
        """Execute an actor attempt; the world oracle independently records stale acceptance."""
        if self.state['stopped']:
            return {'result': 'acceptance_suppressed_by_stop'}
        if not self.state['flags']['ai_available']:
            return self._stop('ai_priority_unavailable')
        # A job aid is a procedure, not an unpurchased physical interlock.
        item = {'alarm': 'alarm-A', 'at': self.clock, 'display_used': copy.deepcopy(self.state['display']),
                'stale': self.state['display'] != self.truth,
                'checked_before_acceptance': self.state['inspection'] == 'current'}
        self.state['accepted_items'].append(item)
        return {'result': 'stale_item_accepted' if item['stale'] else 'current_item_accepted',
                'protocol_violation': not item['checked_before_acceptance']}

    def _handoff(self, payload: dict) -> dict:
        """Transmit the frozen fields once during the purchased handoff segment."""
        if not self.state['stopped']:
            return {'result': 'handoff_not_required'}
        report = {'alarm': 'alarm-A', 'last_known_values_uncertain': True,
                  'timestamp': self.state['display']['timestamp'], 'contradiction': self.state['inspection'],
                  'ai_priority': 'alarm-A' if self.state['flags']['ai_available'] else 'unavailable',
                  'stopped_status': True}
        self.state.update(handoff_attempted=True, handoff_payload=report)
        if not self.state['flags']['radio_available']:
            return {'result': 'handoff_packet_dropped', 'payload': report}
        self.schedule(self.clock + self.time['ack_delay'], 'acknowledge')
        return {'result': 'handoff_sent', 'payload': report}

    def _acknowledge(self, payload: dict) -> dict:
        """Require actual modeled channel and recipient availability for acknowledgement."""
        complete = set(self.state['handoff_payload']) == set(self.program.handoff_fields)
        ready = (self.state['flags']['radio_available'] and self.state['flags']['recipient_available']
                 and self.clock <= self.time['handoff_window_end'] and complete)
        if ready:
            self.state['ack_at'] = self.clock
        return {'result': 'handoff_acknowledged' if ready else 'handoff_unacknowledged',
                'required_fields_complete': complete}

    def _paper_check(self, payload: dict) -> dict:
        """Execute the frozen refusal to use uncertain paper values to clear a stop."""
        return {'result': 'uncertain_paper_cannot_clear_stop', 'stop_remains': self.state['stopped']}

    def _environment(self, payload: dict) -> dict:
        """Apply an external fault or restoration without giving the actor future information."""
        self.state['flags'].update(payload)
        return {'result': 'environment_changed', 'changes': payload}

    def _finish(self, payload: dict) -> dict:
        """Close at the frozen time limit without erasing earlier errors or inventing assessment."""
        if self.state['withheld']:
            terminal = 'withheld'
        elif self.state['stopped']:
            terminal = 'stopped_with_ack' if self.state['ack_at'] is not None else 'stopped_without_ack'
        else:
            terminal = 'completed_current_record_path'
        self.state['phase'] = terminal
        return {'result': terminal, 'independent_diagnosis_assessed': False, 'delayed_transfer_assessed': False}

    def _execute(self, kind: str, payload: dict) -> dict:
        """Dispatch events with no branch on difficulty labels or preset outcome fields."""
        if self.state['withheld'] and kind not in ['environment', 'finish']:
            return {'result': 'suppressed_after_withheld_start'}
        if kind in ['inspect', 'accept', 'handoff', 'paper_check'] and not self.state['practice_started']:
            return {'result': 'suppressed_before_practice'}
        handler = getattr(self, '_' + kind)
        return handler(payload)

    def run(self) -> dict:
        """Execute every scheduled transition and return raw software observations, not prose scores."""
        while self.queue:
            self.clock, _, kind, payload = heapq.heappop(self.queue)
            before = copy.deepcopy(self.state)
            observation = self._execute(kind, payload)
            event = {'seq': len(self.trace) + 1, 'at_seconds': self.clock, 'event': kind,
                     'input': payload, 'observation': observation, 'before': before,
                     'after': copy.deepcopy(self.state), 'previous_sha256': self.previous}
            encoded = json.dumps(event, sort_keys=True, separators=(',', ':')).encode()
            event['sha256'] = hashlib.sha256(encoded).hexdigest()
            self.previous = event['sha256']
            self.trace.append(event)
        return {'scenario_id': self.scenario['id'], 'difficulty': self.scenario['difficulty'],
                'kind': self.scenario['kind'], 'behavior_profile': self.scenario['behavior_profile'],
                'freeze_sha256': self.program.sha256, 'input': copy.deepcopy(self.scenario),
                'final_state': copy.deepcopy(self.state), 'trace': self.trace,
                'trace_tail_sha256': self.previous, 'evidence_kind': 'executed_software_simulation'}
"""Derive executable deployment outcomes and competency dependencies from recorded transitions."""
from __future__ import annotations

import hashlib
import json


def verify_trace(episode: dict) -> None:
    """Reject altered, reordered or discontinuous transitions before reporting any outcome."""
    previous = episode['freeze_sha256']
    last_time = -1
    last_state = None
    for index, event in enumerate(episode['trace'], 1):
        raw = {k: v for k, v in event.items() if k != 'sha256'}
        expected = hashlib.sha256(json.dumps(raw, sort_keys=True, separators=(',', ':')).encode()).hexdigest()
        if event['sha256'] != expected or event['previous_sha256'] != previous:
            raise ValueError('Trace hash chain broken')
        if event['seq'] != index or event['at_seconds'] < last_time:
            raise ValueError('Trace ordering broken')
        if last_state is not None and event['before'] != last_state:
            raise ValueError('State-transition continuity broken')
        previous, last_time, last_state = expected, event['at_seconds'], event['after']
    if previous != episode['trace_tail_sha256'] or last_state != episode['final_state']:
        raise ValueError('Terminal state does not match observed trace')


def outcomes(episode: dict) -> dict:
    """Compute event-level successes and failures without consulting difficulty or role names."""
    verify_trace(episode)
    state = episode['final_state']
    stale_acceptances = [x for x in state['accepted_items'] if x['stale']]
    acknowledgements = [e for e in episode['trace'] if e['observation']['result'] == 'handoff_acknowledged']
    stops = [e for e in episode['trace'] if e['observation']['result'] == 'stopped']
    uncovered = set()
    for event in episode['trace']:
        flags = event['after']['flags']
        uncovered.update(name for key, name in [('ai_available', 'ai_loss'), ('radio_available', 'radio_dropout')]
                         if not flags[key])
        if flags.get('cascading_alerts'):
            uncovered.add('cascading_alerts')
    containment = not stale_acceptances
    completed = state['practice_started'] and containment and not uncovered and (
        bool(acknowledgements) if state['stopped'] else bool(state['accepted_items']))
    return {'practice_started': state['practice_started'], 'start_withheld': state['withheld'],
            'stale_items_accepted': len(stale_acceptances),
            'first_stale_acceptance_at_seconds': stale_acceptances[0]['at'] if stale_acceptances else None,
            'first_stop_at_seconds': stops[0]['at_seconds'] if stops else None,
            'stop_latched': state['stopped'], 'handoff_attempted': state['handoff_attempted'],
            'handoff_acknowledged': bool(acknowledgements),
            'acknowledgement_at_seconds': acknowledgements[0]['at_seconds'] if acknowledgements else None,
            'containment_obligation_met': containment,
            'deployment_demand_fulfilled': completed,
            'uncovered_features_encountered': sorted(uncovered),
            'release_boundary_obeyed': not (state['withheld'] and state['practice_started']),
            'paper_cleared_stop': state['paper_cleared_stop'],
            'independent_diagnosis_assessed': False, 'delayed_transfer_assessed': False,
            'human_learning_outcome': None, 'terminal_state': state['phase']}


def dependency_findings(episodes: list[dict]) -> list[dict]:
    """Identify functional requirements with trace witnesses, without inferring team superiority."""
    by_id = {e['scenario_id']: e for e in episodes}
    pairs = [
        ('cue_use_and_assessment', ['medium', 'medium_cue_first'],
         'A check must be performed before accepting ranked data; a supplied job aid does not demonstrate that behavior.',
         'Learning research and assessment define the uncued performance evidence needed; operational design makes the cue usable.',
         'The behavior profile is an authored timing assumption. This comparison is not an effect of training.'),
        ('reference_and_release_engineering', ['easy', 'missing_reference'],
         'An actual checked reference is a precondition for practice; an absent reference must prevent start.',
         'Systems engineering supplies verifiable state/reference rules and release gates.',
         'The reference is local scripted truth, not a calibrated or independently verified utility clock.'),
        ('coordination_and_communication', ['easy', 'recipient_unavailable', 'hard_after_start'],
         'A stopped operator needs a reachable recipient and delivered acknowledgement; naming a team member is insufficient.',
         'Operational coordination and systems reliability jointly determine whether the handoff can complete.',
         'No retry or replacement communication channel was added to the frozen intervention.'),
        ('scope_and_coverage', ['hard', 'hard_after_start'],
         'Correct refusal can preserve a release boundary while leaving the combined deployment demand unmet.',
         'Systems thinking distinguishes component containment, end-to-end capability, unavailable resources and recovery.',
         'The deployment test environment can impose a radio fault; the intervention still lacks radio-failure rehearsal.'),
    ]
    findings = []
    for fid, ids, requirement, competencies, limitation in pairs:
        witnesses = {sid: {'trace_tail_sha256': by_id[sid]['trace_tail_sha256'],
                           'outcomes': outcomes(by_id[sid])} for sid in ids}
        findings.append({'id': fid, 'functional_requirement': requirement,
                         'competency_implication': competencies, 'witnesses': witnesses,
                         'limitation': limitation})
    return findings
"""Run and retain reproducible executable deployment episodes for the unchanged frozen intervention."""
from __future__ import annotations

import argparse
import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path

from controlroom_contract import compile_program, read_json
from controlroom_results import dependency_findings, outcomes
from controlroom_simulator import DeploymentSimulator


def sha(path: Path) -> str:
    """Hash exact implementation or evidence bytes for a retained execution receipt."""
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write_new(path: Path, data: dict) -> None:
    """Retain each result once without overwriting a prior execution or failure."""
    with path.open('x') as handle:
        json.dump(data, handle, indent=2, ensure_ascii=False)
        handle.write('\n')


def execute(root: Path, model_path: Path, folder: Path) -> dict:
    """Run every declared episode after pinning code and inputs, then report derived observations."""
    folder.mkdir(parents=True, exist_ok=False)
    model = read_json(model_path)
    program = compile_program(root, model)
    implementation = [Path(__file__).parent / name for name in [
        'controlroom_contract.py', 'controlroom_simulator.py', 'controlroom_results.py',
        'run_controlroom_deployment.py']]
    receipt = {'description': 'Implementation/input receipt written before the first deployment episode.',
               'started_at': datetime.now(timezone.utc).isoformat(), 'freeze_sha256': program.sha256,
               'model_sha256': sha(model_path), 'implementation_sha256': {p.name: sha(p) for p in implementation},
               'model_is_retrospective': True, 'new_design_agent_calls': 0,
               'evidence_kind': 'executed_software_simulation',
               'limitation': model['interpretation']}
    write_new(folder / 'execution-receipt.json', receipt)
    episodes = []
    try:
        for scenario in model['scenarios']:
            episode = DeploymentSimulator(program, model, scenario).run()
            episode['outcomes'] = outcomes(episode)
            write_new(folder / f'{scenario["id"]}.json', episode)
            episodes.append(episode)
        summary = summarize(program.sha256, model, episodes)
        write_new(folder / 'summary.json', summary)
        write_new(folder / 'competency-dependencies.json', {
            'description': 'Trace-supported functional competency and coordination requirements, not team-versus-individual effects.',
            'findings': dependency_findings(episodes),
            'team_vs_individual': 'These functions could be distributed across a team or held by an appropriately competent and authorized individual. No matched individual design or team-size effect was tested.'})
        if sha(root / model['frozen_path']) != program.sha256:
            raise ValueError('Frozen input changed during executable deployment')
        return summary
    except Exception as error:
        write_new(folder / 'execution-failure.json', {'description': 'Actual failed executable deployment retained without repair.',
                  'error_type': type(error).__name__, 'error': str(error), 'completed_episodes': len(episodes)})
        raise


def summarize(freeze: str, model: dict, episodes: list[dict]) -> dict:
    """Separate primary results, diagnostic probes and authored assumptions in one compact index."""
    rows = [{'scenario_id': e['scenario_id'], 'difficulty': e['difficulty'], 'kind': e['kind'],
             'behavior_profile': e['behavior_profile'], 'trace_tail_sha256': e['trace_tail_sha256'],
             'outcomes': e['outcomes']} for e in episodes]
    return {'description': 'Observed software-state outcomes of one unchanged frozen intervention, not written deployment projections or human observations.',
            'model_id': model['model_id'], 'freeze_sha256': freeze,
            'evidence_kind': 'executed_software_simulation', 'primary_episodes': [r for r in rows if r['kind'] == 'primary'],
            'diagnostic_probes': [r for r in rows if r['kind'] != 'primary'],
            'assumptions': model['assumptions'], 'objectives': model['objectives'],
            'interpretation': model['interpretation'], 'replay': 'Fixed model and implementation reproduce episode traces and outcomes; wall-clock receipt timestamps differ.'}


def main() -> None:
    """Expose an API-key-free simulator CLI with explicit model and new output paths."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', type=Path, default=Path.cwd())
    parser.add_argument('--model', type=Path, default=Path('src/data/lifecycle/controlroom-deployment-v1.json'))
    parser.add_argument('--out', type=Path, required=True)
    args = parser.parse_args()
    result = execute(args.root, args.model, args.out)
    print(json.dumps({'primary_episodes': result['primary_episodes'],
                      'diagnostic_probe_count': len(result['diagnostic_probes'])}, indent=2))


if __name__ == '__main__':
    main()
"""Exercise stateful deployment failures, scope gates, provenance and assumption sensitivity."""
import copy
import json
from pathlib import Path
import sys
import unittest
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT / 'tools/lifecycle'))
from controlroom_contract import compile_program, read_json
from controlroom_results import outcomes, verify_trace
from controlroom_simulator import DeploymentSimulator, freshness_status


class DeploymentTest(unittest.TestCase):
    """Test transitions and counterexamples rather than authored narrative labels."""

    def setUp(self) -> None:
        """Load the unmodified frozen plan and explicit synthetic environment contract."""
        self.model = read_json(ROOT / 'src/data/lifecycle/controlroom-deployment-v1.json')
        self.program = compile_program(ROOT, self.model)

    def run_case(self, sid: str, change: dict | None = None) -> dict:
        """Execute an independent episode, optionally perturbing a declared condition."""
        scenario = copy.deepcopy(next(s for s in self.model['scenarios'] if s['id'] == sid))
        if change:
            scenario.update(change)
        result = DeploymentSimulator(self.program, self.model, scenario).run()
        result['outcomes'] = outcomes(result)
        return result

    def test_easy_stops_before_acceptance_and_receives_ack(self) -> None:
        """Observe completed containment/handoff while keeping diagnosis unassessed."""
        o = self.run_case('easy')['outcomes']
        self.assertTrue(o['practice_started'])
        self.assertEqual((o['stale_items_accepted'], o['first_stop_at_seconds'],
